type User={id:string;role:'WORKER'|'ASSESSOR'|'REVIEWER'|'ADMIN';displayName:string;hasProfile:boolean;authorizedOccupationIds?:string[]};

const API_BASE = ((import.meta as any).env?.VITE_API_BASE_URL || '').replace(/\/$/, '');

const api = async (path: string, init: RequestInit = {}) => {
  const url = `${API_BASE}${path.startsWith('/') ? path : `/${path}`}`;
  const r = await fetch(url, {
    credentials: 'include',
    ...init,
    headers: {
      'Content-Type': 'application/json',
      ...(init.headers || {}),
    },
  });
  const d = await r.json().catch(() => ({}));
  if (!r.ok) {
    throw Object.assign(new Error(d.error || `Request failed (${r.status})`), {
      response: d,
      status: r.status,
    });
  }
  return d;
};

