 const load=useCallback(async()=>{const version=++loadVersion.current;try{const d=await api('/api/worker/dashboard');const chosen=d.profile?.occupationId||occupationId||d.occupations?.[0]?.id;const c=await api('/api/catalogue?occupationId='+encodeURIComponent(chosen));if(version!==loadVersion.current)return;setDash(d);setCat(c);void api('/api/notifications').then((n:any)=>setNotifications(n.items||[])).catch(()=>{});const packs=c.qualificationPacks||[];setQualificationPackId(current=>packs.some((p:any)=>p.id===current)?current:packs[0]?.id||'');void readWorkerDraft(me.id).then(setLocalDraft).catch(()=>{});setOccupationId(chosen);onSummary({profile:d.profile,assessments:d.assessments,reports:d.reports,catalogue:c});if(d.profile){setConsent(!!d.profile.consent);setName(d.profile.name);setYears(String(d.profile.yearsExperience));setLanguage(d.profile.language);setOccupationId(d.profile.occupationId||chosen);setExperienceSource(d.profile.experienceSource||'');setExperienceSummary(d.profile.experienceSummary||'');setSelected(d.profile.taskIds);setAssessmentTaskId(current=>d.profile.taskIds.includes(current)?current:(d.profile.taskIds[0]||''));setDescription(d.profile.description||'')}}catch(e:any){if(version===loadVersion.current)setMessage('Could not refresh your saved records. '+e.message)}},[onSummary,occupationId,me.id]);useEffect(()=>{void load()},[load,refreshKey]);
 async function action(fn:()=>Promise<any>,success:string){try{await fn();setMessage(success);await load();onChange();return true}catch(e:any){setMessage(e.message);return false}}
 async function saveDeviceDraft(){const draft={occupationId,taskIds:selected,description,consent,expectedUpdatedAt:dash.profile?.declaration?.updatedAt||null,savedAt:new Date().toISOString()};try{await writeWorkerDraft(me.id,draft);setLocalDraft(draft);setMessage(t(lang,'offlineDraft'))}catch(e:any){setMessage(e.message)}}
